oai = String(oai || '').trim();
var negs = ['unfortunately','regret','sorry','cannot','unable','not qualified','lack of','no experience','weak','poor','fail'];
var kws = prep.keywords || [];
function score(t) {
  t = String(t || '');
  if (t.length < 60) return -1;
  var lt = t.toLowerCase();
  var hits = 0; for (var i = 0; i < kws.length; i++) { if (kws[i] && lt.indexOf(String(kws[i]).toLowerCase()) !== -1) hits++; }
  var density = t.length > 0 ? (hits / (t.length / 500)) : 0;
  var neg = 0; for (var n = 0; n < negs.length; n++) { if (lt.indexOf(negs[n]) !== -1) neg++; }
  var lenScore = Math.min(t.length, 3500) / 3500;
  return lenScore * 0.4 + Math.min(density, 10) * 0.06 + (hits * 0.03) - (neg * 0.15);
}
