var prep = $('Prep Row').first().json || {};
var company = String(prep.company || '');
var email = String(prep.recipient || '').toLowerCase().trim();
var jd = String(prep.job_description || '');
var score = 0;
var reasons = [];
var kwBlock = false;
// Check 1 (first, cheap, high-signal): email domain vs company domain
var emailDomain = '';
var at = email.indexOf('@');
if (at !== -1) emailDomain = email.slice(at + 1);
var freeProviders = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','protonmail.com','mail.com','yandex.com','gmx.com','ymail.com'];
var isFree = false;
for (var i = 0; i < freeProviders.length; i++) { if (emailDomain === freeProviders[i]) { isFree = true; break; } }
var compToken = company.toLowerCase().replace(/[^a-z0-9]/g, '');
var domainCore = (emailDomain.split('.')[0]) || '';
var domainMatches = false;
if (compToken && domainCore && domainCore.length >= 3) { if (compToken.indexOf(domainCore) !== -1 || domainCore.indexOf(compToken.slice(0, 5)) !== -1) domainMatches = true; }
if (isFree) { score += 25; reasons.push('Free-mail domain (' + emailDomain + ') used for company ' + company); }
else if (emailDomain && compToken && !domainMatches) { score += 10; reasons.push('Email domain ' + emailDomain + ' does not obviously match company name'); }
// Description length
var words = jd ? jd.split(/\s+/).filter(function (w) { return w.length > 0; }).length : 0;
if (words > 0 && words < 100) { score += 15; reasons.push('Job description under 100 words (' + words + ')'); }
// Scam keywords -> auto-block
var scamKw = ['training fee','equipment purchase','bank details','bank account number','national id','processing fee','registration fee','pay a deposit','western union','send money','upfront payment','activation fee'];
var hay = (jd + ' ' + company).toLowerCase();
for (var k = 0; k < scamKw.length; k++) { if (hay.indexOf(scamKw[k]) !== -1) { score += 40; reasons.push('Scam keyword detected: ' + scamKw[k]); kwBlock = true; } }
if (score > 100) score = 100;
var decision = 'proceed';
if (score >= 85) decision = 'blocked';
else if (score >= 60) decision = 'flagged';
if (kwBlock) decision = 'blocked';
var reasonText = reasons.length ? reasons.join('; ') : 'No suspicious signals detected';
return [{ json: Object.assign({}, prep, { scam_score: score, scam_decision: decision, scam_reasons: reasonText }) }];

var j = $input.first().json || {};
var cv = String(j.tailored_cv || '');
var cover = String(j.cover_letter || '');
var warnings = [];
var redacted = false;
// Saudi national ID: 10 digits starting with 1 or 2
var reNid = /\b[12]\d{9}\b/g;
// Saudi/general IBAN
var reIban = /\b[A-Z]{2}\d{2}[A-Z0-9]{11,30}\b/g;
// Passport-like: 1-2 letters + 6-8 digits
var rePass = /\b[A-Z]{1,2}\d{6,8}\b/g;
// Long bank-account-like digit runs (12+)
var reBank = /\b\d{12,}\b/g;
function scrub(text, label) {
  var t = text;
  var patterns = [ ['national_id', reNid], ['iban', reIban], ['passport', rePass], ['bank_account', reBank] ];
  for (var i = 0; i < patterns.length; i++) {
    var name = patterns[i][0]; var re = patterns[i][1];
    if (re.test(t)) { warnings.push(name + ' pattern found in ' + label); redacted = true; }
    t = t.replace(re, '[REDACTED]');
  }
  return t;
}
cv = scrub(cv, 'CV');
cover = scrub(cover, 'cover letter');
// Always append STOP line to cover letter
var stopLine = 'If you\u2019d prefer not to receive future applications from this platform, reply STOP.';
if (cover.indexOf('reply STOP') === -1) { cover = cover + '\n\n' + stopLine; }
return [{ json: { row_id: j.row_id, company: j.company, recipient: j.recipient, tailored_cv: cv, cover_letter: cover, cv_agent: j.cv_agent || '', cover_agent: j.cover_agent || '', tone_score: j.tone_score, tone_flagged: j.tone_flagged, pii_redacted: redacted, pii_warnings: warnings.join('; ') } }];

var limitRaw = 15;
try { var c = $('Get Send Limit').first().json; if (c && c.config_value !== undefined && c.config_value !== null && String(c.config_value).length) { var pv = parseInt(String(c.config_value), 10); if (!isNaN(pv)) limitRaw = pv; } } catch (e) {}
var enabled = false;
try { var g = $('Get Guard Flag').first().json; if (g && String(g.config_value).toLowerCase() === 'true') enabled = true; } catch (e) {}
var rows = [];
try { rows = $('Get Sent Today').all(); } catch (e) { rows = []; }
var now = new Date();
var startToday = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0);
var endToday = startToday + (24 * 60 * 60 * 1000);
var sentToday = 0;
for (var i = 0; i < rows.length; i++) {
  var r = rows[i].json || {};
  if (!r || Object.keys(r).length === 0) continue;
  var pa = r.processed_at ? Date.parse(r.processed_at) : NaN;
  if (!isNaN(pa) && pa >= startToday && pa < endToday) sentToday++;
}
var limitReached = enabled && (sentToday >= limitRaw);
return [{ json: { guard_enabled: enabled, daily_limit: limitRaw, sent_today: sentToday, limit_reached: limitReached } }];

